import { describe, expect, it } from 'vitest'
import { buildBlockCatalogue } from '~~/server/utils/builderCatalogue'
import { parseDocument } from '~~/server/utils/builderDocument'
import { BUILDER_DOCUMENT_ROOTS } from '~~/shared/builder/documentRoots'
import { convertLegacyLayout } from '~~/shared/builder/fromLegacy'
import type { LegacySection } from '~~/shared/builder/fromLegacy'
import type { BlockDefinition } from '~~/shared/types/builder'

/**
 * What Django's seeds are tested against, committed so it cannot rot.
 *
 * Two files under `test/fixtures/builder/`, each regenerated by running
 * `pnpm vitest run --project=unit test/unit/server/utils/builderSeeds.spec.ts -u`
 * and reviewed in the diff:
 *
 * - `catalogue.json`: the catalogue payload of this build for the default
 *   schema (`GET /api/builder/catalogue`, which is the same for every store
 *   today), pretty-printed. A block or a document-root change fails the spec
 *   until the file is regenerated; Django vendors it, pinned.
 * - `seeds/home.json`: the platform's default home, `DEFAULT_PAGE_LAYOUTS["home"]`
 *   of Django's `page_config/defaults.py`, as `convert-legacy` converts it: the
 *   request and the response, whose `document` and `i18n` are the seed. A new
 *   store gets it as its first release.
 *
 * Reads the REAL blocks of `app/blocks`. Vitest caches this file's transform,
 * globs included: after ADDING a block file locally, edit this comment once or
 * it is not seen (CI starts clean).
 */
const modules = import.meta.glob<{ default: BlockDefinition }>('../../../../app/blocks/*.block.ts', { eager: true })
const definitions = Object.values(modules).map(({ default: block }) => block)
const registry = new Map(definitions.map(block => [block.type, block]))

/**
 * The section ids of the home seed: fixed, so the seed is the same bytes
 * every time and a store's first release names the same ids as every other
 * store's. `5eed` marks them as seed ids; the last four digits are the
 * section's position in the layout, from 01.
 */
const seedId = (position: number) => `00000000-0000-4000-8000-5eed0000${String(position).padStart(4, '0')}`

/** `DEFAULT_PAGE_LAYOUTS["home"]` as Django stores it (snake_case props), in its order. */
const HOME: ReadonlyArray<readonly [type: string, props: Record<string, unknown>]> = [
  ['hero_carousel', {}],
  ['trust_badges', { surface: 'default' }],
  ['product_categories', { surface: 'default', layout: 'tiles' }],
  ['products_grid', { ordering: 'newest', surface: 'muted' }],
  ['offers_preview', { surface: 'ink' }],
  ['featured_products', { ordering: 'popular', surface: 'default' }],
  ['loyalty_hero', { surface: 'default' }],
  ['stats_strip', { surface: 'default' }],
  ['blog_posts_grid', { surface: 'muted' }],
  ['testimonials', { surface: 'default' }],
  ['faq', { surface: 'muted' }],
]

const sections: LegacySection[] = HOME.map(([type, props], index) => ({
  id: seedId(index + 1),
  type,
  title: '',
  isVisible: true,
  props,
}))

const request = {
  schema: 'default',
  kind: 'template' as const,
  key: 'template:home',
  defaultLocale: 'el',
  legacy: { pageType: 'home', title: 'Homepage', seo: {}, sections },
}

const converted = () => convertLegacyLayout(request.legacy, {
  kind: request.kind,
  defaultLocale: request.defaultLocale,
  registry,
  roots: BUILDER_DOCUMENT_ROOTS,
})

describe('the catalogue snapshot', () => {
  it('is what this build generates', async () => {
    await expect(`${JSON.stringify(buildBlockCatalogue(definitions), null, 2)}\n`)
      .toMatchFileSnapshot('../../../fixtures/builder/catalogue.json')
  })
})

describe('the home seed', () => {
  it('is the default home converted: its request and the response Django stores', async () => {
    await expect(`${JSON.stringify({ request, response: converted() }, null, 2)}\n`)
      .toMatchFileSnapshot('../../../fixtures/builder/seeds/home.json')
  })

  it('keeps the eleven sections of the layout, in its order, under the fixed ids', () => {
    const { document, warnings } = converted()

    expect(document.order).toEqual(HOME.map((_, index) => seedId(index + 1)))
    expect(document.order.map(id => document.sections[id]!.type.split('@')[0])).toEqual(HOME.map(([type]) => type))
    expect(warnings).toEqual([])
  })

  it('is valid against the catalogue it is snapshotted beside: every section survives the parse', () => {
    const { document } = converted()

    const parsed = parseDocument(document, 'template', registry)

    expect(parsed.order).toEqual(document.order)
    expect(parsed.sections).toEqual(document.sections)
  })

  it('is a document of a template that exists in the catalogue', () => {
    expect(buildBlockCatalogue(definitions).templates).toContain('home')
  })
})
